        'key' => 'business', 'label' => 'Your Business', 'order' => 10, 'view' => 'money::setup/install',
        'data' => static fn(array $state): array => Setup::installData($state),
        'save' => static fn(\AP\Core\Request $request, array $state): array => Setup::installSave($request),
        'summary' => static fn(array $value): string => Setup::describe($value),
        'apply' => static fn(\AP\Core\DB $db, \AP\Core\Settings $settings, array $value, array $state): array => ['Your business: ' . Setup::result(Setup::apply($db, $settings, $value))],
    ],
    'search' => [
        'money_income' => ['label' => 'Income', 'icon' => 'fa-hand-holding-dollar', 'permission' => 'money.view', 'limit' => 5,
            'handler' => static function (string $term, int $limit): array {
                if (!Money::ready()) {
                    return [];
                }
                $rows = Money::db()->table('money_income')->whereNull('deleted_at')->search(['title', 'description', 'reference'], $term)->orderBy('income_date', 'desc')->limit($limit)->get();
                return array_map(static fn($r) => ['title' => (string) $r['title'], 'subtitle' => Money::showDate((string) $r['income_date']) . ' · ' . Money::gbp($r['amount']),
                    'url' => admin_url('money/income/' . (int) $r['id']), 'icon' => 'fa-hand-holding-dollar', 'score' => 3], $rows);
            }],
        'money_invoices' => ['label' => 'Invoices', 'icon' => 'fa-file-invoice', 'permission' => 'money.view', 'limit' => 5,
            'handler' => static function (string $term, int $limit): array {
                if (!Money::ready()) {
                    return [];
                }
                $rows = Money::db()->table('money_invoices')->whereNull('deleted_at')->search(['number', 'note'], $term)->orderBy('issue_date', 'desc')->limit($limit)->get();
                return array_map(static fn($r) => ['title' => 'Invoice ' . $r['number'], 'subtitle' => Money::showDate((string) $r['issue_date']) . ' · ' . Money::gbp($r['total']),
                    'url' => admin_url('money/invoices/' . (int) $r['id']), 'icon' => 'fa-file-invoice', 'score' => 3], $rows);
            }],
        'money_expenses' => ['label' => 'Expenses', 'icon' => 'fa-receipt', 'permission' => 'money.view', 'limit' => 5,
            'handler' => static function (string $term, int $limit): array {
                if (!Money::ready()) {
                    return [];
                }
                $rows = Money::db()->table('money_expenses')->whereNull('deleted_at')->search(['title', 'description'], $term)->orderBy('expense_date', 'desc')->limit($limit)->get();
                return array_map(static fn($r) => ['title' => (string) $r['title'], 'subtitle' => Money::showDate((string) $r['expense_date']) . ' · ' . Money::gbp($r['amount']),
